queries:
SELECT AVG(invoice_ratio) AS overall_average_cost_ratio
FROM (
  SELECT invoice_number,
         AVG(derived_product_cost * 1.0 / derived_total_cost) AS invoice_ratio
  FROM Invoice_Line_Items
  GROUP BY invoice_number
);
SELECT AVG(derived_product_cost * 1.0 / derived_total_cost) FROM Invoice_Line_Items WHERE derived_total_cost <> 0;
SELECT invoice_number, COUNT(*) AS line_items_count FROM Invoice_Line_Items GROUP BY invoice_number;
SELECT invoice_number, COUNT(DISTINCT order_item_id) AS line_items_count FROM Invoice_Line_Items GROUP BY invoice_number
SELECT invoice_number, COUNT(DISTINCT product_id) AS line_items_count
FROM Invoice_Line_Items
GROUP BY invoice_number;
